/* @autogenerated */
import { signal } from '@angular/core';
import { TestBed } from '@angular/core/testing';
import { ActivatedRoute, Router } from '@angular/router';
import { BehaviorSubject } from 'rxjs';
import { AppStateService } from '@shared/context/state/app-state.service';
import { DefaultsService } from '@shared/context/config/defaults.service';
import { ContainerComponent } from './container.component';

describe('ContainerComponent', () => {
  let router: jasmine.SpyObj<Router>;
  let params: BehaviorSubject<Record<string, string>>;
  let state: { language: ReturnType<typeof signal<string>>; tenant: ReturnType<typeof signal<string>> };
  let route: any;

  const create = () => {
    TestBed.configureTestingModule({
      imports: [ContainerComponent],
      providers: [
        { provide: Router, useValue: router },
        { provide: ActivatedRoute, useValue: route },
        { provide: AppStateService, useValue: state },
        { provide: DefaultsService, useValue: { language: () => 'es', tenant: () => 'main' } },
      ],
    });
    TestBed.overrideTemplate(ContainerComponent, '');
    const fixture = TestBed.createComponent(ContainerComponent);
    fixture.detectChanges();
    return fixture;
  };

  beforeEach(() => {
    router = jasmine.createSpyObj<Router>('Router', ['navigate']);
    params = new BehaviorSubject<Record<string, string>>({ language: 'en', tenant: 'acme' });
    state = { language: signal('en'), tenant: signal('acme') };
    route = {
      params,
      root: {},
      snapshot: { url: [{ path: 'en' }, { path: 'acme' }], firstChild: { url: [{ path: 'users' }], firstChild: null } },
    };
  });

  afterEach(() => TestBed.resetTestingModule());

  it('leaves the url alone when it already has the language and the tenant', () => {
    create();

    expect(router.navigate).not.toHaveBeenCalled();
    expect(state.language()).toBe('en');
    expect(state.tenant()).toBe('acme');
  });

  it('takes the language and the tenant of the url', () => {
    params.next({ language: 'fr', tenant: 'other' });
    create();

    expect(state.language()).toBe('fr');
    expect(state.tenant()).toBe('other');
  });

  it('puts the chosen language in the url, keeping the rest of the path', () => {
    state.language.set('fr');
    params.next({ language: 'fr', tenant: 'acme' });
    create();

    expect(router.navigate).toHaveBeenCalledWith(['fr', 'acme', 'users'], {
      queryParamsHandling: 'merge',
      relativeTo: route.root,
    });
  });

  it('falls back to the default language and tenant', () => {
    state.language.set('');
    state.tenant.set('');
    params.next({});
    create();

    expect(router.navigate).toHaveBeenCalledWith(['es', 'acme', 'users'], jasmine.anything());
    expect(router.navigate).toHaveBeenCalledWith(['en', 'main', 'users'], jasmine.anything());
  });

  it('stops following the url when destroyed', () => {
    const fixture = create();
    fixture.destroy();

    params.next({ language: 'de', tenant: 'later' });

    expect(state.language()).toBe('en');
    expect(state.tenant()).toBe('acme');
  });
});
